def experiment(inputs):
    import random
    params = inputs.get('parameters', {})
    seeds = inputs.get('seeds', [42])
    results = {}
    for seed in seeds:
        random.seed(seed)
        vals = [random.gauss(0, 1) for _ in range(5)]
        results[str(seed)] = vals
    return {"measurements": {"error_rate": [sum(v)/len(v) for v in results.values()]}}

